-- 0046: mode 4 "เดินตรวจห้องเครื่อง" gets a chemicals group (user 2026-11-16: SDS/MSDS and the labels a chemical must carry).
-- 8 central items, group MR8. Additive only: inserts new rows, skips any already there. Existing FMS 05 items stay as they are.
insert into public.fms_items (hospital_id, kind, cat, cat_name, no, text, ref, red)
select null, v.kind, v.cat, v.cat_name, v.no, v.text, v.ref, v.red from (values
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2001, 'มีบัญชีสารเคมีของห้องนี้ (คลอรีน สารเคมีหอระบายความร้อน น้ำยาบำบัดน้ำ น้ำมันเชื้อเพลิง น้ำกลั่นแบตเตอรี่ สารทำความเย็น) เป็นปัจจุบัน ตรงกับของจริง', 'FMS.05.00 ME 2', false),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2002, 'SDS (MSDS) ภาษาไทยฉบับปัจจุบัน (ไม่เกิน 5 ปี) ของสารเคมีทุกตัวในห้อง อยู่ ณ จุดเก็บ/จุดใช้ หยิบดูได้ทันที', 'FMS.05.00 ME 3', true),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2003, 'ภาชนะสารเคมีทุกใบมีฉลาก: ชื่อสาร สัญลักษณ์อันตราย GHS คำเตือน วิธีปฐมพยาบาล และชื่อผู้ผลิต/ผู้จำหน่าย', 'FMS.05.00 ME 3', true),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2004, 'ขวด/ถังที่แบ่งบรรจุมีฉลากชื่อสารและสัญลักษณ์อันตรายเหมือนภาชนะเดิม ไม่ใช้ขวดน้ำดื่มใส่สารเคมี', 'FMS.05.00 ME 3', true),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2005, 'หน้าห้อง/ที่เก็บสารเคมีมีป้ายเตือนอันตราย และป้าย PPE ที่ต้องสวม', 'FMS.05.00 ME 3', false),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2006, 'จัดเก็บแยกสารที่ทำปฏิกิริยากัน (เช่น คลอรีนกับกรด) มีถาดรองรับการหก ฝาปิดสนิท', 'FMS.05.00 ME 3', true),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2007, 'มี PPE ตาม SDS (ถุงมือ แว่น หน้ากาก) และ Spill kit ไม่หมดอายุ ใกล้จุดเก็บสารเคมี', 'FMS.05.00 ME 5', false),
  ('walk', 'MR8', 'ห้องเครื่อง · สารเคมีในห้องเครื่อง (SDS / ฉลาก)', 2008, 'ที่ล้างตา/ฝักบัวฉุกเฉินเดินถึงภายใน 10 วินาที มีบันทึกเปิดน้ำทดสอบรายสัปดาห์ และช่างตอบขั้นตอนเมื่อสารเคมีหกหรือเข้าตาได้', 'FMS.05.00 ME 5', true)
) as v(kind, cat, cat_name, no, text, ref, red)
where not exists (select 1 from public.fms_items i where i.hospital_id is null and i.kind = v.kind and i.cat = v.cat and i.no = v.no);
